namespace docking.widgets.textfield;








using docking.util;
using generic.theme.GThemeDefaults.Colors;
using generic.theme;

public class HexOrDecimalInput : JTextField {
	private static readonly string FONT_ID = "font.input.hint";
	private bool isHexMode = false;
	private bool allowsNegative = true;
	private Long currentValue;

	public HexOrDecimalInput() : this(null)
    {
	}

	public HexOrDecimalInput(int columns) : base(columns)
    {
		init(null);
	}

	public HexOrDecimalInput(Long initialValue) {
		init(initialValue);
	}

	private void init(Long initialValue) {
		currentValue = initialValue;
		setDocument(new MyDocument());
		updateText();
		setToolTipText("Press 'M' to toggle Hex or Decimal Mode");
		addKeyListener(new _Anon_KeyAdapter_1());
	}

	public Long getValue() {
		return currentValue;
	}

	public int getIntValue() {
		if (currentValue == null) {
			return 0;
		}
		return currentValue.intValue();
	}

	public void setValue(int newValue) {
		setValue((long) newValue);
	}

	public void setValue(Long newValue) {
		if (!allowsNegative && newValue != null && newValue.longValue() < 0) {
			currentValue = null;
		}
		currentValue = newValue;
		updateText();
	}

	private void toggleMode() {
		if (isHexMode) {
			setDecimalMode();
		}
		else {
			setHexMode();
		}
	}

	public void setHexMode() {
		isHexMode = true;
		updateText();
	}

	private void updateText() {
		setText(computeTextForCurrentValue());
	}

	private string computeTextForCurrentValue() {
		if (currentValue == null) {
			return "";
		}
		string stringValue;
		long value = currentValue;
		long absValue = value < 0 ? -value : value;
		if (isHexMode) {
			stringValue = Long.toHexString(absValue);
		}
		else {
			stringValue = Long.toString(absValue);
		}
		if (value < 0) {
			stringValue = "-" + stringValue;
		}
		return stringValue;
	}

	public void setDecimalMode() {
		isHexMode = false;
		updateText();
	}

	/* @Override */
	protected void paintComponent(Graphics g) {
		base.paintComponent(g);
		Font font = Gui.getFont(FONT_ID);
		Font savedFont = g.getFont();
		g.setFont(font);
		g.setColor(Messages.HINT);
		FontMetrics fontMetrics = getFontMetrics(font);
		string mode = isHexMode ? "Hex" : "Dec";
		int stringWidth = fontMetrics.stringWidth(mode);
		Dimension size = getSize();
		Insets insets = getInsets();
		int x = size.width - insets.right - stringWidth;
		int y = size.height - insets.bottom;
		GraphicsUtils.drawString(this, g, mode, x, y);
		g.setFont(savedFont);
	}

	public void setAllowNegative(bool b) {
		allowsNegative = b;
		if (!allowsNegative) {
			if (currentValue != null && currentValue.longValue() < 0) {
				currentValue = null;
			}
		}
		updateText();
	}

	private Long computeValueFromString(string text) {
		if (text.length() == 0) {
			return null;
		}

		bool isNegative = false;
		long value = 0;
		if (text.startsWith("-")) {
			isNegative = true;
			text = text.substring(1);
		}
		if (isHexMode) {
			value = Long.parseUnsignedLong(text, 16);
		}
		else {
			value = Long.parseLong(text);
		}
		if (isNegative) {
			value = -value;
		}
		return value;
	}

	private class MyDocument : PlainDocument {

		private MyDocument() : base()
    {
		}

		/**
		 * @see javax.swing.text.Document#insertString(int, java.lang.String, javax.swing.text.AttributeSet)
		 */
		/* @Override */
		public void insertString(int offs, string str, AttributeSet a)
    {
			if (str == null) {
				return;
			}
			if (!checkChars(str)) {
				return;
			}
			StringBuilder builder = new StringBuilder(this.getText());
			builder.insert(offs, str);
			string newText = builder.toString();

			int lastIndexOf = newText.lastIndexOf('-');
			if (lastIndexOf > 0) {
				return;  // not allowed anywhere except at the start
			}

			if (!newText.equals("-")) {
				try {
					currentValue = computeValueFromString(newText);
				}
				catch (NumberFormatException e) {
					return;
				}
			}
			base.insertString(offs, str, a);
		}

		/* @Override */
		public void remove(int offs, int len)
    {
			base.remove(offs, len);
			string newText = this.getText();
			if (newText.length() == 0 || newText.equals("-")) {
				currentValue = null;
			}
			else {
				currentValue = computeValueFromString(newText);
			}
		}

		private bool checkChars(string text) {
			for (int i = 0; i < text.length(); i++) {
				char c = text.charAt(i);
				if (!checkChar(c)) {
					return false;
				}
			}
			return true;
		}

		private bool checkChar(char c) {
			if (allowsNegative && c == '-') {
				return true;
			}
			if (c >= '0' && c <= '9') {
				return true;
			}
			if (isHexMode && c >= 'a' && c <= 'f') {
				return true;
			}
			if (isHexMode && c >= 'A' && c <= 'F') {
				return true;
			}
			return false;
		}
	}

