	internal class _Anon_KeyAdapter_1 : KeyAdapter
	{

			/* @Override */
			public void keyPressed(KeyEvent e) {
				if (e.getKeyCode() == KeyEvent.VK_M) {
					toggleMode();
					repaint();
				}
			}

		
	}

}
